// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        amount = bound(amount, 0, 1 ether);

        AttackerHighGas attacker = new AttackerHighGas();

        vm.deal(address(c), amount);

        address target = (seed % 2 == 0) ? address(attacker) : address(0xBEEF);

        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract AttackerHighGas {
    receive() external payable {
        uint256 i = 0;
        while (i < 100) {
            i++;
        }
    }
}
